/* Liquid Glass — Apple 2026: bright room, ultra-translucent panels,
   refraction highlights, adaptive blur, specular hairline borders */
.theme-liquid-glass {
  --bg: oklch(0.96 0.012 250);
  --surface: oklch(1 0 0 / 42%);
  --surface-2: oklch(1 0 0 / 62%);
  --fg: oklch(0.24 0.02 260);
  --fg-muted: oklch(0.48 0.02 260);
  --accent: oklch(0.62 0.17 255);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.7 0.14 200);
  --line: oklch(1 0 0 / 70%);
  --success: oklch(0.68 0.15 155);
  --warning: oklch(0.8 0.14 82);
  --danger: oklch(0.62 0.2 22);

  --radius: 1.5rem;
  --radius-sm: 1rem;
  --radius-lg: 2.25rem;
  --radius-pill: 9999px;

  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 90%), inset 0 -1px 0 oklch(1 0 0 / 45%),
    0 1px 2px oklch(0.3 0.03 260 / 10%);
  --shadow-2: inset 0 1px 0 oklch(1 0 0 / 95%), inset 0 -12px 24px oklch(1 0 0 / 30%),
    0 12px 34px -14px oklch(0.35 0.04 260 / 32%);
  --shadow-3: inset 0 1.5px 0 oklch(1 0 0 / 95%), inset 0 -20px 40px oklch(1 0 0 / 35%),
    0 30px 70px -26px oklch(0.35 0.04 260 / 38%);
  --glow: 0 0 0 1px oklch(1 0 0 / 80%), 0 0 40px -10px oklch(0.62 0.17 255 / 45%);

  --border-width: 1px;
  --blur-amount: 28px;

  --font-display: "Geist", "Inter", sans-serif;
  --font-body: "Geist", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.03em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  background-image:
    radial-gradient(48rem 30rem at 6% -6%, oklch(0.86 0.11 250 / 75%), transparent 62%),
    radial-gradient(44rem 30rem at 96% 4%, oklch(0.9 0.09 190 / 70%), transparent 62%),
    radial-gradient(56rem 36rem at 46% 108%, oklch(0.88 0.1 320 / 60%), transparent 66%),
    linear-gradient(180deg, oklch(0.985 0.008 250), oklch(0.93 0.02 250));
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-liquid-glass h1,
.theme-liquid-glass h2,
.theme-liquid-glass h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

/* Specular sheen that reads as refracted light across translucent panels. */
.theme-liquid-glass [class*="rounded-theme"] {
  background-image: linear-gradient(
    180deg,
    oklch(1 0 0 / 45%) 0%,
    oklch(1 0 0 / 10%) 38%,
    oklch(1 0 0 / 0%) 62%,
    oklch(1 0 0 / 22%) 100%
  );
}

/* signature */
.theme-liquid-glass button { box-shadow: inset 0 1px 0 oklch(1 0 0 / 60%), 0 4px 16px oklch(0 0 0 / 10%); }
.theme-liquid-glass h1 { letter-spacing: -0.045em; font-weight: 600; }

/* depth */
.theme-liquid-glass thead th { color: var(--fg-muted); font-size: 0.72em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.07em; border-bottom: 1px solid oklch(0.3 0.03 260 / 14%); background: oklch(1 0 0 / 35%); }
.theme-liquid-glass td { border-bottom: 1px solid oklch(0.3 0.03 260 / 8%); }
.theme-liquid-glass tbody tr:hover { background: oklch(1 0 0 / 40%); }
.theme-liquid-glass input, .theme-liquid-glass textarea, .theme-liquid-glass select { background: oklch(1 0 0 / 55%); border: 1px solid oklch(1 0 0 / 80%); box-shadow: inset 0 1px 2px oklch(0.3 0.03 260 / 10%); border-radius: var(--radius-sm); }
.theme-liquid-glass input:focus-visible, .theme-liquid-glass textarea:focus-visible, .theme-liquid-glass select:focus-visible { outline: none; border-color: color-mix(in oklab, var(--accent) 55%, oklch(1 0 0 / 80%)); box-shadow: inset 0 1px 2px oklch(0.3 0.03 260 / 8%), 0 0 0 4px color-mix(in oklab, var(--accent) 22%, transparent); }
.theme-liquid-glass kbd { background: linear-gradient(180deg, oklch(1 0 0 / 95%), oklch(1 0 0 / 60%)); border: 1px solid oklch(0.7 0.02 260 / 50%); border-radius: 0.45em; padding: 0.1em 0.45em; box-shadow: inset 0 1px 0 oklch(1 0 0), 0 1px 2px oklch(0.3 0.03 260 / 20%); font-family: var(--font-mono); font-size: 0.85em; }
.theme-liquid-glass a { color: var(--accent); text-decoration: none; }
.theme-liquid-glass a:hover { text-decoration: underline; text-underline-offset: 0.2em; text-decoration-thickness: 1.5px; }
.theme-liquid-glass ::selection { background: color-mix(in oklab, var(--accent) 28%, transparent); }
.theme-liquid-glass ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-liquid-glass ::-webkit-scrollbar-track { background: transparent; }
.theme-liquid-glass ::-webkit-scrollbar-thumb { background: oklch(0.5 0.03 260 / 35%); border-radius: 9999px; border: 3px solid transparent; background-clip: padding-box; }
.theme-liquid-glass ::-webkit-scrollbar-thumb:hover { background: oklch(0.5 0.03 260 / 55%); border: 3px solid transparent; background-clip: padding-box; }
.theme-liquid-glass .label-caps { color: var(--fg-muted); font-weight: 600; }
.theme-liquid-glass .themed-border { border-color: oklch(1 0 0 / 75%); box-shadow: 0 0 0 0.5px oklch(0.5 0.03 260 / 18%); }
.theme-liquid-glass button:hover { box-shadow: inset 0 1px 0 oklch(1 0 0 / 80%), 0 6px 20px oklch(0.35 0.04 260 / 16%); }
.theme-liquid-glass button:active { transform: scale(0.985); box-shadow: inset 0 1px 3px oklch(0.3 0.03 260 / 18%); }

/* alt mode: dark room — smoked glass, dim specular hairlines, deep glow */
.theme-liquid-glass.alt-mode {
  --bg: oklch(0.17 0.02 255);
  --surface: oklch(1 0 0 / 8%);
  --surface-2: oklch(1 0 0 / 14%);
  --fg: oklch(0.95 0.008 255);
  --fg-muted: oklch(0.72 0.015 255);
  --accent: oklch(0.656 0.160 255.0);
  --line: oklch(1 0 0 / 18%);
  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 22%), 0 2px 6px oklch(0 0 0 / 40%);
  --shadow-2: inset 0 1px 0 oklch(1 0 0 / 25%), inset 0 -12px 24px oklch(1 0 0 / 4%), 0 12px 34px -12px oklch(0 0 0 / 55%);
  --shadow-3: inset 0 1.5px 0 oklch(1 0 0 / 28%), 0 30px 70px -24px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px oklch(1 0 0 / 20%), 0 0 40px -10px oklch(0.68 0.16 255 / 50%);
  background-image:
    radial-gradient(48rem 30rem at 6% -6%, oklch(0.4 0.1 255 / 45%), transparent 62%),
    radial-gradient(44rem 30rem at 96% 4%, oklch(0.38 0.09 195 / 40%), transparent 62%),
    linear-gradient(180deg, oklch(0.2 0.02 255), oklch(0.14 0.02 255));
}
.theme-liquid-glass.alt-mode [class*="rounded-theme"] { background-image: linear-gradient(180deg, oklch(1 0 0 / 10%) 0%, oklch(1 0 0 / 2%) 38%, oklch(1 0 0 / 0%) 62%, oklch(1 0 0 / 5%) 100%); }
.theme-liquid-glass.alt-mode input, .theme-liquid-glass.alt-mode textarea, .theme-liquid-glass.alt-mode select { background: oklch(1 0 0 / 8%); border-color: oklch(1 0 0 / 20%); color: var(--fg); }
.theme-liquid-glass.alt-mode kbd { background: linear-gradient(180deg, oklch(1 0 0 / 18%), oklch(1 0 0 / 8%)); border-color: oklch(1 0 0 / 25%); box-shadow: inset 0 1px 0 oklch(1 0 0 / 35%), 0 1px 2px oklch(0 0 0 / 40%); }
.theme-liquid-glass.alt-mode thead th { background: oklch(1 0 0 / 6%); border-bottom-color: oklch(1 0 0 / 14%); }
.theme-liquid-glass.alt-mode td { border-bottom-color: oklch(1 0 0 / 8%); }
.theme-liquid-glass.alt-mode tbody tr:hover { background: oklch(1 0 0 / 6%); }
.theme-liquid-glass.alt-mode ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 28%); border: 3px solid transparent; background-clip: padding-box; }
.theme-liquid-glass.alt-mode button { box-shadow: inset 0 1px 0 oklch(1 0 0 / 25%), 0 4px 16px oklch(0 0 0 / 35%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
